def solve(I):
    H=len(I); W=len(I[0]); ac=[c for c in range(W) if I[0][c]!=0]
    a=ac[0]; out=[[0]*W for _ in range(H)]
    # 2s: up-left/up-right diagonals (toward anchor, rows above/left of diagonal through anchor going back to edge)
    for d in (-1,1):
        r=1
        while True:
            rr=r; cc=a+d*r
            if 0<=rr<H and 0<=cc<W:
                out[rr][cc]=2; r+=1
            else: break
        r=-1
        while True:
            rr=r; cc=a+d*r
            if 0<=rr<H and 0<=cc<W:
                out[rr][cc]=2; r-=1
            else: break
    # 1s: down-left/down-right from anchor until hitting left wall or bottom-adjacent band
    for d in (-1,1):
        r=1
        while True:
            rr=a+r if False else None
            cc=a+d*r; val=1 if a-r>=0 and a-d*r<=H-1 else -9
            # only draw if the anti-diagonal cell exists and its mirror would hit wall
            if cc<0 or cc>=W: 
                r+=1
                continue
            rr=r
            if 0<=rr<H:
                out[rr][cc]=val; r+=1
    return out
